<script setup lang="ts">
import {collectionItems} from '~/composables/useBackend'
import type {Counselor} from '~/types/api'
import type {BookingService} from '~/types/booking'
import {todayInTehran} from '~/utils/jalaliDate.mjs'
useSeoMeta({title:'مشاوران',description:'مشاوران و روان‌شناسان مرکز'})
const route=useRoute(),router=useRouter(),query=ref(String(route.query.q||'')),specialtyId=ref(String(route.query.specialty_id||'')),serviceId=ref(String(route.query.service_id||'')),date=ref(String(route.query.date||todayInTehran())),availabilityOnly=ref(route.query.available==='1'),page=computed(()=>Math.max(1,Number(route.query.page)||1)),search=computed(()=>String(route.query.q||'')),specialtyFilter=computed(()=>String(route.query.specialty_id||''))
const requestQuery=computed(()=>({per_page:12,page:page.value,...(search.value?{search:search.value}:{}),...(specialtyFilter.value?{specialty_id:specialtyFilter.value}:{})}))
const {data,error,pending}=await useBackend().counselors(requestQuery)
const {data:specialties}=await useBackend().specialties()
const {data:serviceData}=await useAsyncData('counselor-directory-booking-services',()=>useBookingApi().services())
const api=useBookingApi(),people=computed(()=>collectionItems<Counselor>(data.value)),meta=computed<any>(()=>data.value?.meta||data.value),serviceOptions=computed(()=>collectionItems<BookingService>(serviceData.value)),filteredPeople=ref<Counselor[]>([]),filterBusy=ref(false),filterError=ref('')
let filterGeneration=0
async function applyFilters(){const generation=++filterGeneration;filterBusy.value=!!(serviceId.value||availabilityOnly.value);filterError.value='';if(!serviceId.value){filteredPeople.value=people.value;filterBusy.value=false;return}const results=await Promise.all(people.value.map(async person=>{try{const response=await api.availability(person.id,Number(serviceId.value),date.value);const hasFree=response.slots.some(slot=>slot.available&&new Date(slot.starts_at).getTime()>Date.now());return availabilityOnly.value?!hasFree?null:person:person}catch(e){if((e as any)?.statusCode===422)return null;filterError.value=bookingMessage(e,(key)=>String(key));return null}}));if(generation===filterGeneration){filteredPeople.value=results.filter((item):item is Counselor=>!!item);filterBusy.value=false}}
watch([people,serviceId,date,availabilityOnly],applyFilters,{immediate:true})
async function applySearch(){await router.push({query:{...(query.value.trim()?{q:query.value.trim()}:{}),...(specialtyId.value?{specialty_id:specialtyId.value}:{}),...(serviceId.value?{service_id:serviceId.value}:{}),...(serviceId.value?{date:date.value}:{}),...(availabilityOnly.value?{available:'1'}:{}),page:1}})}
</script>
<template><div class="directory-page"><header class="directory-masthead"><div class="container"><span class="eyebrow">انتخاب آگاهانه</span><h1>مشاور مناسب خود را پیدا کنید</h1><p>پروفایل، حوزه‌های تخصصی و زمان‌های واقعی قابل رزرو را بررسی کنید.</p><form class="directory-filters" @submit.prevent="applySearch"><label class="sr-only" for="counselor-search">جست‌وجو بر اساس نام یا تخصص</label><input id="counselor-search" v-model="query" type="search" placeholder="نام مشاور یا تخصص"><label class="sr-only" for="counselor-specialty">حوزه تخصصی</label><select id="counselor-specialty" v-model="specialtyId"><option value="">همه تخصص‌ها</option><option v-for="item in collectionItems(specialties)" :key="item.id" :value="String(item.id)">{{item.title}}</option></select><label class="sr-only" for="counselor-service">خدمت</label><select id="counselor-service" v-model="serviceId"><option value="">همه خدمات</option><option v-for="item in serviceOptions" :key="item.id" :value="String(item.id)">{{item.title}}</option></select><label class="sr-only">تاریخ بررسی دسترسی</label><JalaliDatePicker v-model="date" label="تاریخ بررسی دسترسی" :min="todayInTehran()" :disabled="!serviceId" /><label class="filter-check"><input v-model="availabilityOnly" type="checkbox" :disabled="!serviceId"> فقط زمان آزاد</label><button class="btn" type="submit">اعمال فیلترها</button></form></div></header><section class="container directory-results"><div class="directory-results-heading"><div><span class="eyebrow">مشاوران مرکز</span><h2>پروفایل‌های عمومی</h2></div><p v-if="meta?.total">{{meta.total}} مشاور</p></div><p v-if="pending||filterBusy">در حال بررسی مشاوران و زمان‌های آزاد…</p><ApiNotice v-else-if="error">دریافت مشاوران از API ناموفق بود.</ApiNotice><ApiNotice v-else-if="filterError">بررسی زمان‌های آزاد ناموفق بود؛ لطفاً دوباره تلاش کنید.</ApiNotice><div v-else-if="filteredPeople.length" class="counselor-grid"><CounselorCard v-for="person in filteredPeople" :key="person.id" :person="person"/></div><ApiNotice v-else>مشاوری با این مشخصات یا زمان آزاد پیدا نشد.</ApiNotice><nav v-if="Number(meta?.last_page)>1" class="pager"><NuxtLink v-if="page>1" class="btn secondary" :to="{query:{...(search?{q:search}:{}),...(specialtyFilter?{specialty_id:specialtyFilter}:{}),...(serviceId?{service_id:serviceId}:{}),page:page-1}}">قبلی</NuxtLink><span>صفحه {{page}} از {{meta.last_page}}</span><NuxtLink v-if="page<meta.last_page" class="btn secondary" :to="{query:{...(search?{q:search}:{}),...(specialtyFilter?{specialty_id:specialtyFilter}:{}),...(serviceId?{service_id:serviceId}:{}),page:page+1}}">بعدی</NuxtLink></nav></section></div></template>
